const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function webLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '';return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;}catch{return '';}}
function emailLink(email){if(!email)return '';return /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)?`<a href="mailto:${esc(encodeURIComponent(email))}">${esc(email)}</a>`:esc(email);}
function phoneLink(phone){if(!phone)return '';const main=phone.split('(')[0].trim();const digits=main.replace(/[^+\d]/g,'');return digits.length>=5?`<a href="tel:${esc(digits)}">${esc(phone)}</a>`:esc(phone);}
export function renderContacts(contacts=[]){
 const available=contacts.filter(c=>['contact_name','directory_email','verified_professional_email','telephone','linkedin_url'].some(k=>c[k]));
 if(!available.length)return '<p class="prose">No public contact found</p>';
 return available.map(c=>`<article class="panel content-pad contact-card"><h3>${esc(c.contact_name||'Company contact')}</h3><div class="contact-grid">${c.verified_professional_email?`<div><span class="contact-label">Verified professional email</span>${emailLink(c.verified_professional_email)}</div>`:''}${c.directory_email&&c.directory_email!==c.verified_professional_email?`<div><span class="contact-label">Public directory email · unverified</span>${emailLink(c.directory_email)}${c.email_classification?`<small>${esc(c.email_classification)}</small>`:''}</div>`:''}${c.telephone?`<div><span class="contact-label">Public directory telephone</span>${phoneLink(c.telephone)}</div>`:''}${c.job_title?`<div><span class="contact-label">Role</span>${esc(c.job_title)}</div>`:'<div><span class="contact-label">Role</span>Unverified</div>'}${c.linkedin_url?`<div><span class="contact-label">Professional profile</span>${webLink(c.linkedin_url,'LinkedIn profile')}</div>`:''}</div><p class="note">${esc(c.verification_status||'Directory-listed; role unverified')}${c.decision_maker_relevance===true?' · Relevant decision-maker verified':''}</p>${webLink(c.contact_source,'Contact source')}${c.published_date?`<span class="contact-date">Recorded ${esc(c.published_date)}</span>`:''}</article>`).join('')+'<p class="note">Publicly listed contacts. Directory names, job roles and email deliverability have not been independently verified. A directory contact is not automatically a decision-maker.</p>';
}
